window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8259cd49eba966ed"]={"versions": [{"id": "FIG-8259cd49eba966ed", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware-Architektur- und Klassifikationsdiagramm der AUTOSAR Classic Platform (Microcontroller Abstraction Layer, MCAL, LIN Driver). Das Diagramm stellt die Zuordnung und strukturelle Einbettung verschiedener Typen von LIN-Hardware-Einheiten innerhalb eines Mikrocontrollers (µCtr) dar und visualisiert deren Anbindung über diskrete Pins und Transceiver-Bausteine an unabhängige LIN-Cluster. Ein exemplarischer Pfad ist durch eine rote Ellipse und die Beschriftung „LIN physical channel“ hervorgehoben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Mikrocontroller (<code>µCtr</code>)</strong>: Zentraler Host-Controller mit drei exemplarischen Ausprägungen von LIN-Hardware-Einheiten:</li>\n<li><code>LIN Hardware Unit A</code>: Enthält mehrere dedizierte Hardware-LIN-Controller (<code>LIN Controller 0</code>, <code>LIN Controller 1</code>, ..., <code>LIN Controller n</code>).</li>\n<li><code>LIN Hardware Unit B</code>: Basiert auf Standard-UART/SCI-Schnittstellen (<code>SCI/UART 0</code>, <code>SCI/UART 1</code>).</li>\n<li><code>LIN Hardware Unit C</code>: Basiert auf erweiterten Schnittstellen (<code>Enhanced SCI/UART 0</code>, <code>Enhanced SCI/UART 1</code>) mit spezifischer LIN-Hardwareunterstützung.</li>\n<li><strong>Schnittstellen (Mikrocontroller zu Transceiver)</strong>: Unidirektionale digitale Logiksignale je Controller:</li>\n<li><code>TxD 0</code> bis <code>TxD n</code> bzw. <code>TxD 1</code> (Sendedaten vom Controller zum Transceiver).</li>\n<li><code>RxD 0</code> bis <code>RxD n</code> bzw. <code>RxD 1</code> (Empfangsdaten vom Transceiver zum Controller).</li>\n<li><strong>Transceiver ICs</strong>: Externe physikalische Bus-Treiber (<code>Transceiver IC A</code>, <code>Transceiver IC B</code>, ..., <code>Transceiver IC N</code>, <code>Transceiver IC N+1</code>, <code>Transceiver IC N+2</code>, <code>Transceiver IC N+3</code>, <code>Transceiver IC N+4</code>) zur Signalpegelwandlung zwischen MCU-Logikpegel und Buspegel.</li>\n<li><strong>LIN-Netzwerke (<code>LIN cluster A</code> bis <code>LIN cluster N+4</code>)</strong>: Physikalisch getrennte LIN-Busse, die jeweils über bidirektionale Busleitungen 1:1 an genau einen Transceiver IC angebunden sind.</li>\n<li><strong>LIN physical channel</strong>: Durch eine rote Ellipse gekennzeichnete funktionale Einheit aus Controller-Pins (TxD 0, RxD 0), Transceiver IC A und Anbindung an LIN cluster A.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsmodell ohne Darstellung von temporaler Sequenz, Zustandsübergängen oder API-Aufrufketten. Der Signalfluss erfolgt kanalweise und strikt isoliert:</p>\n<ul class=\"fig-list\">\n<li><strong>Senden</strong>: Der MCAL-Treiber übergibt Frame-Daten an den jeweiligen Controller-Kanal; serielle Bitströme werden über <code>TxD</code> an den zugeordneten Transceiver IC geleitet und auf den Eindraht-Bus moduliert.</li>\n<li><strong>Empfangen</strong>: Buszustände werden vom Transceiver IC erfasst, in Logikpegel umgewandelt und über <code>RxD</code> an die Hardware-Einheit zurückgeführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Architektur und Konfiguration des AUTOSAR LIN-Treibers (MCAL):</p>\n<ul class=\"fig-list\">\n<li>Der Treiber muss einheitliche standardisierte Schnittstellen (<code>Lin_Init</code>, <code>Lin_SendFrame</code> etc.) über heterogenen Hardware-Einheiten bereitstellen (dedizierte LIN-Controller, Standard-UART/SCI, Enhanced SCI).</li>\n<li>Bei Standard-UART/SCI (<code>Unit B</code>) muss der Treiber Frame-Elemente wie Synch Break Generation/Detection softwarebasiert oder per Baudraten-/Timer-Umschaltung steuern, während <code>Unit A</code> und <code>Unit C</code> dies in Hardware abwickeln.</li>\n<li>Das Diagramm visualisiert die normative Begriffsabgrenzung des „LIN physical channel“: Ein physischer LIN-Kanal umfasst die MCU-Pins (TxD/RxD), das externe Transceiver-IC sowie die Verbindung zum LIN-Cluster.</li>\n<li>Feste 1:1-Kardinalität: Jeder logische LIN-Kanal ist exklusiv genau einem Transceiver-IC und genau einem LIN-Cluster zugeordnet.</li>\n</ul>"}, {"id": "FIG-3c51a75fbd26c5f0", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware-Architektur- und Klassifikationsdiagramm der AUTOSAR Classic Platform (Microcontroller Abstraction Layer, MCAL, LIN Driver). Das Diagramm stellt die Zuordnung und strukturelle Einbettung verschiedener Typen von LIN-Hardware-Einheiten innerhalb eines Mikrocontrollers (µCtr) dar und visualisiert deren Anbindung über diskrete Pins und Transceiver-Bausteine an unabhängige LIN-Cluster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Mikrocontroller (<code>µCtr</code>)</strong>: Zentraler Host-Controller mit drei exemplarischen Ausprägungen von LIN-Hardware-Einheiten:</li>\n<li><code>LIN Hardware Unit A</code>: Enthält mehrere dedizierte Hardware-LIN-Controller (<code>LIN Controller 0</code>, <code>LIN Controller 1</code>, ..., <code>LIN Controller n</code>).</li>\n<li><code>LIN Hardware Unit B</code>: Basiert auf Standard-UART/SCI-Schnittstellen (<code>SCI/UART 0</code>, <code>SCI/UART 1</code>).</li>\n<li><code>LIN Hardware Unit C</code>: Basiert auf erweiterten Schnittstellen (<code>Enhanced SCI/UART 0</code>, <code>Enhanced SCI/UART 1</code>) mit spezifischer LIN-Hardwareunterstützung.</li>\n<li><strong>Schnittstellen (Mikrocontroller zu Transceiver)</strong>: Unidirektionale digitale Logiksignale je Controller:</li>\n<li><code>TxD 0</code> bis <code>TxD n</code> bzw. <code>TxD 1</code> (Sendedaten vom Controller zum Transceiver).</li>\n<li><code>RxD 0</code> bis <code>RxD n</code> bzw. <code>RxD 1</code> (Empfangsdaten vom Transceiver zum Controller).</li>\n<li><strong>Transceiver ICs</strong>: Externe physikalische Bus-Treiber (<code>Transceiver IC A</code>, <code>Transceiver IC B</code>, ..., <code>Transceiver IC N</code>, <code>Transceiver IC N+1</code>, <code>Transceiver IC N+2</code>, <code>Transceiver IC N+3</code>, <code>Transceiver IC N+4</code>) zur Signalpegelwandlung zwischen MCU-Logikpegel und Buspegel.</li>\n<li><strong>LIN-Netzwerke (<code>LIN cluster A</code> bis <code>LIN cluster N+4</code>)</strong>: Physikalisch getrennte LIN-Busse, die jeweils über bidirektionale Busleitungen 1:1 an genau einen Transceiver IC angebunden sind.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsmodell ohne Darstellung von temporaler Sequenz, Zustandsübergängen oder API-Aufrufketten. Der Signalfluss erfolgt kanalweise und strikt isoliert:</p>\n<ul class=\"fig-list\">\n<li><strong>Senden</strong>: Der MCAL-Treiber übergibt Frame-Daten an den jeweiligen Controller-Kanal; serielle Bitströme werden über <code>TxD</code> an den zugeordneten Transceiver IC geleitet und auf den Eindraht-Bus moduliert.</li>\n<li><strong>Empfangen</strong>: Buszustände werden vom Transceiver IC erfasst, in Logikpegel umgewandelt und über <code>RxD</code> an die Hardware-Einheit zurückgeführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Architektur und Konfiguration des AUTOSAR LIN-Treibers (MCAL):</p>\n<ul class=\"fig-list\">\n<li>Der Treiber muss einheitliche standardisierte Schnittstellen (<code>Lin_Init</code>, <code>Lin_SendFrame</code> etc.) über heterogenen Hardware-Einheiten bereitstellen (dedizierte LIN-Controller, Standard-UART/SCI, Enhanced SCI).</li>\n<li>Bei Standard-UART/SCI (<code>Unit B</code>) muss der Treiber Frame-Elemente wie Synch Break Generation/Detection softwarebasiert oder per Baudraten-/Timer-Umschaltung steuern, während <code>Unit A</code> und <code>Unit C</code> dies in Hardware abwickeln.</li>\n<li>Fokus auf Hardware-Klassifikation: Die Zuordnung definiert das Mapping von MCAL-Kanälen auf Hardware-Einheiten, während die Definition des physischen Kanals primär im Spezifikationstext geführt wird.</li>\n<li>Feste 1:1-Kardinalität: Jeder logische LIN-Kanal ist exklusiv genau einem Transceiver-IC und genau einem LIN-Cluster zugeordnet.</li>\n</ul>"}, {"id": "FIG-e08d621b629aa45a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Hardware-Architektur- und Klassifikationsdiagramm der AUTOSAR Classic Platform (Microcontroller Abstraction Layer, MCAL, LIN Driver). Das Diagramm stellt die Zuordnung und strukturelle Einbettung verschiedener Typen von LIN-Hardware-Einheiten innerhalb eines Mikrocontrollers (µCtr) dar und visualisiert deren Anbindung über diskrete Pins und Transceiver-Bausteine an unabhängige LIN-Cluster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Mikrocontroller (<code>µCtr</code>)</strong>: Zentraler Host-Controller mit drei exemplarischen Ausprägungen von LIN-Hardware-Einheiten:</li>\n<li><code>LIN Hardware Unit A</code>: Enthält mehrere dedizierte Hardware-LIN-Controller (<code>LIN Controller 0</code>, <code>LIN Controller 1</code>, ..., <code>LIN Controller n</code>).</li>\n<li><code>LIN Hardware Unit B</code>: Basiert auf Standard-UART/SCI-Schnittstellen (<code>SCI/UART 0</code>, <code>SCI/UART 1</code>).</li>\n<li><code>LIN Hardware Unit C</code>: Basiert auf erweiterten Schnittstellen (<code>Enhanced SCI/UART 0</code>, <code>Enhanced SCI/UART 1</code>) mit spezifischer LIN-Hardwareunterstützung.</li>\n<li><strong>Schnittstellen (Mikrocontroller zu Transceiver)</strong>: Unidirektionale digitale Logiksignale je Controller:</li>\n<li><code>TxD 0</code> bis <code>TxD n</code> bzw. <code>TxD 1</code> (Sendedaten vom Controller zum Transceiver).</li>\n<li><code>RxD 0</code> bis <code>RxD n</code> bzw. <code>RxD 1</code> (Empfangsdaten vom Transceiver zum Controller).</li>\n<li><strong>Transceiver ICs</strong>: Externe physikalische Bus-Treiber (<code>Transceiver IC A</code>, <code>Transceiver IC B</code>, ..., <code>Transceiver IC N</code>, <code>Transceiver IC N+1</code>, <code>Transceiver IC N+2</code>, <code>Transceiver IC N+3</code>, <code>Transceiver IC N+4</code>) zur Signalpegelwandlung zwischen MCU-Logikpegel und Buspegel.</li>\n<li><strong>LIN-Netzwerke (<code>LIN cluster A</code> bis <code>LIN cluster N+4</code>)</strong>: Physikalisch getrennte LIN-Busse, die jeweils über bidirektionale Busleitungen 1:1 an genau einen Transceiver IC angebunden sind.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsmodell ohne Darstellung von temporaler Sequenz, Zustandsübergängen oder API-Aufrufketten. Der Signalfluss erfolgt kanalweise und strikt isoliert:</p>\n<ul class=\"fig-list\">\n<li><strong>Senden</strong>: Der MCAL-Treiber übergibt Frame-Daten an den jeweiligen Controller-Kanal; serielle Bitströme werden über <code>TxD</code> an den zugeordneten Transceiver IC geleitet und auf den Eindraht-Bus moduliert.</li>\n<li><strong>Empfangen</strong>: Buszustände werden vom Transceiver IC erfasst, in Logikpegel umgewandelt und über <code>RxD</code> an die Hardware-Einheit zurückgeführt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Architektur und Konfiguration des AUTOSAR LIN-Treibers (MCAL):</p>\n<ul class=\"fig-list\">\n<li>Der Treiber muss einheitliche standardisierte Schnittstellen (<code>Lin_Init</code>, <code>Lin_SendFrame</code> etc.) über heterogenen Hardware-Einheiten bereitstellen (dedizierte LIN-Controller, Standard-UART/SCI, Enhanced SCI).</li>\n<li>Bei Standard-UART/SCI (<code>Unit B</code>) muss der Treiber Frame-Elemente wie Synch Break Generation/Detection softwarebasiert oder per Baudraten-/Timer-Umschaltung steuern, während <code>Unit A</code> und <code>Unit C</code> dies in Hardware abwickeln.</li>\n<li>Fokus auf Hardware-Klassifikation: Die Zuordnung definiert das Mapping von MCAL-Kanälen auf Hardware-Einheiten, während die Definition des physischen Kanals primär im Spezifikationstext geführt wird.</li>\n<li>Feste 1:1-Kardinalität: Jeder logische LIN-Kanal ist exklusiv genau einem Transceiver-IC und genau einem LIN-Cluster zugeordnet.</li>\n</ul>"}], "trans": [{"from": "FIG-8259cd49eba966ed", "to": "FIG-3c51a75fbd26c5f0", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>LIN physical channel</code>: Die rote Ellipse um Kanal 0 (TxD 0, RxD 0, Transceiver IC A, Verbindung zum LIN cluster A) und die rote Beschriftung „LIN physical channel“ wurden ersatzlos entfernt.</li>\n<li><code>LIN Hardware Unit A</code>, <code>B</code>, <code>C</code>: Hintergrundfüllung der drei Komponenten-Blöcke innerhalb des Mikrocontrollers von Weiß auf Grau geändert.</li>\n</ul>"}, {"from": "FIG-3c51a75fbd26c5f0", "to": "FIG-e08d621b629aa45a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
